/**
 * Un-defaults every session this user has pointed at `orgId` — called when
 * their membership there ends, so the app stops trying to reopen a workspace
 * they can no longer act in. Their other sessions and other orgs are untouched.
 */
export async function clearActiveOrgForUser(
  userId: UserId,
  orgId: OrgId,
): Promise<void> {
  getDb()
    .update(sessions)
    .set({ activeOrgId: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(eq(sessions.userId, userId), eq(sessions.activeOrgId, orgId)))
    .run();
}

/**
 * Un-defaults every session pointed at `orgId`, regardless of whose it is —
 * called when the workspace itself is deleted.
 */
export async function clearActiveOrgForOrg(orgId: OrgId): Promise<void> {
  getDb()
    .update(sessions)
    .set({ activeOrgId: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(sessions.activeOrgId, orgId))
    .run();
}

